t.script:
window.addEventListener('load', function () {
    var placesKey = "";
    var input = document.getElementById('olxStreet');
    var listEl = document.getElementById('olxPlacesList');
    var selCommune = document.getElementById('olxCommune');
    var debounceTimer = null;

    // Blindaje extra: si algún otro script intenta deshabilitar #olxStreet, lo mantiene editable
    if (input) {
        var keepEditable = function () {
            if (input.disabled || input.readOnly) {
                input.disabled = false;
                input.readOnly = false;
            }
            if (input.classList.contains('gm-err-autocomplete')) {
                input.classList.remove('gm-err-autocomplete');
                input.style.backgroundImage = 'none';
            }
        };
        window.gm_authFailure = keepEditable;
        new MutationObserver(keepEditable).observe(input, {
            attributes: true,
            attributeFilter: ['disabled', 'readonly', 'class', 'style']
        });
    }

    // 1) Autocompletado directo con Places API (New) en #olxStreet (sin cargar maps/api/js legacy)
    if (input && listEl && placesKey && placesKey.length > 10) {
        input.addEventListener('input', function () {
            var q = input.value.trim();
            clearTimeout(debounceTimer);
            if (q.length < 3) {
                listEl.style.display = 'none';
                listEl.innerHTML = '';
                return;
            }
            debounceTimer = setTimeout(function () {
                fetch('https://places.googleapis.com/v1/places:autocomplete', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Goog-Api-Key': placesKey
                    },
                    body: JSON.stringify({
                        input: q,
                        includedRegionCodes: ['cl'],
                        languageCode: 'es',
                        locationBias: {
                            circle: {
                                center: { latitude: -33.385, longitude: -70.545 },
                                radius: 15000.0
                            }
                        }
                    })
                })
                .then(function (r) { return r.json(); })
                .then(function (data) {
                    listEl.innerHTML = '';
                    var suggestions = (data && data.suggestions) || [];
                    if (!suggestions.length) {
                        listEl.style.display = 'none';
                        return;
                    }
                    suggestions.forEach(function (s) {
                        var pred = s.placePrediction;
                        if (!pred || !pred.text) return;
                        var fullText = pred.text.text || '';
                        var mainText = (pred.structuredFormat && pred.structuredFormat.mainText && pred.structuredFormat.mainText.text) || fullText.split(',')[0];
                        var secText = (pred.structuredFormat && pred.structuredFormat.secondaryText && pred.structuredFormat.secondaryText.text) || '';
                        var li = document.createElement('li');
                        li.className = 'list-group-item list-group-item-action py-2 small';
                        li.style.cursor = 'pointer';
                        li.innerHTML = '' + mainText + '' + (secText ? ' ' + secText + '' : '');
                        li.addEventListener('mousedown', function (ev) {
                            ev.preventDefault();
                            input.value = mainText;
                            input.dispatchEvent(new Event('input', { bubbles: true }));
                            input.dispatchEvent(new Event('change', { bubbles: true }));
                            var low = fullText.toLowerCase();
                            if (selCommune) {
                                if (low.indexOf('barnechea') !== -1) selCommune.value = 'lo_barnechea';
                                else if (low.indexOf('condes') !== -1) selCommune.value = 'las_condes';
                                else if (low.indexOf('vitacura') !== -1) selCommune.value = 'vitacura';
                                selCommune.dispatchEvent(new Event('change', { bubbles: true }));
                            }
                            listEl.style.display = 'none';
                        });
                        listEl.appendChild(li);
                    });
                    listEl.style.display = 'block';
                })
                .catch(function () {
                    listEl.style.display = 'none';
                });
            }, 250);
        });

        input.addEventListener('blur', function () {
            setTimeout(function () { listEl.style.display = 'none'; }, 200);
        });
    }

    // 2) Recálculo en vivo de tarifa de despacho al ingresar RUT o correo
    var rutEl = document.getElementById('olxRut');
    var emailEl = document.getElementById('olxEmail');
    var grandEl = document.getElementById('olxGrandTotal');
    var bagToggle = document.querySelector('.olx-bag-toggle');
    var modeRadios = document.querySelectorAll('input.olx-mode');

    function fmtClp(n) {
        return '$' + Math.round(n || 0).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    }

    function refreshGrandTotal() {
        if (!grandEl) return;
        var base = parseInt(grandEl.getAttribute('data-base') || '0', 10);
        var ship = parseInt(grandEl.getAttribute('data-ship') || '0', 10);
        var bag = (bagToggle && bagToggle.checked)
            ? parseInt(bagToggle.getAttribute('data-price') || '0', 10) : 0;
        var isDeliv = false;
        modeRadios.forEach(function (r) {
            if (r.checked && r.value === 'delivery') isDeliv = true;
        });
        var shipRows = document.querySelectorAll('.olx-ship-row');
        shipRows.forEach(function (row) {
            if (isDeliv) row.removeAttribute('hidden');
            else row.setAttribute('hidden', 'hidden');
        });
        grandEl.textContent = fmtClp(base + bag + (isDeliv ? ship : 0));
    }

    function fetchShippingQuote() {
        var rutVal = rutEl ? rutEl.value.trim() : '';
        var emailVal = emailEl ? emailEl.value.trim() : '';
        if (!rutVal && !emailVal) return;
        fetch('/prendas/checkout/shipping-quote', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: '2.0', method: 'call',
                params: { rut: rutVal, email: emailVal }
            })
        })
        .then(function (r) { return r.json(); })
        .then(function (res) {
            var q = res && res.result;
            if (!q || !grandEl) return;
            grandEl.setAttribute('data-ship', q.final_fee || 0);
            var optLabel = document.getElementById('olxShipOptLabel');
            var ddEl = document.getElementById('olxShipDd');
            var dtEl = document.getElementById('olxShipDt');
            if (optLabel) {
                var html = 'Lo Barnechea, Las Condes y Vitacura. ';
                if (q.free_by_threshold) {
                    if (q.standard_fee) html += '' + fmtClp(q.standard_fee) + ' ';
                    html += 'Sin costo.';
                } else if (q.is_member && q.member_discount_pct > 0 && q.standard_fee > 0) {
                    html += '' + fmtClp(q.standard_fee) + ' ';
                    html += q.final_fee ? ('Costo ' + fmtClp(q.final_fee) + ' ') : 'Sin costo ';
                    html += '(' + q.member_discount_pct + '% dcto. Suscriptora OulaLab).';
                } else if (q.final_fee) {
                    html += 'Costo ' + fmtClp(q.final_fee) + '.';
                } else {
                    html += 'Sin costo.';
                }
                optLabel.innerHTML = html;
            }
            if (dtEl) {
                dtEl.innerHTML = 'Despacho' + (q.is_member && q.member_discount_pct > 0
                    ? '' + q.member_discount_pct + '% dcto. Suscriptora'
                    : '');
            }
            if (ddEl) {
                var ddHtml = '';
                if (q.discount_amount > 0 && q.standard_fee > 0) {
                    ddHtml += '' + fmtClp(q.standard_fee) + '';
                }
                ddHtml += '' + (q.final_fee ? fmtClp(q.final_fee) : 'Gratis') + '';
                ddEl.innerHTML = ddHtml;
            }
            refreshGrandTotal();
        })
        .catch(function () {});
    }

    if (rutEl) rutEl.addEventListener('blur', fetchShippingQuote);
    if (emailEl) emailEl.addEventListener('blur', fetchShippingQuote);
    if (bagToggle) bagToggle.addEventListener('change', refreshGrandTotal);
    modeRadios.forEach(function (r) { r.addEventListener('change', refreshGrandTotal); });
});
